{
  "findings": [
    {
      "title": "Sample size calculation inconsistent with primary analysis method",
      "page": 85,
      "quote": "This sample size will yield >85% power to detect a treatment difference of 24% in the proportion of patients achieving IGA hand and foot (0, 1) at week 16 between placebo (10%) and dupilumab (34%) at a 2-sided significant level of 5% using Chi-square test",
      "severity": "major"
    },
    {
      "title": "Primary endpoint analysis method differs from sample size calculation",
      "page": 86,
      "quote": "The primary endpoint of proportion of patients achieving an IGA score of 0 or 1 on hand and foot at week 16 will be analyzed using the Cochran-Mantel-Haenszel (CMH) test",
      "severity": "major"
    },
    {
      "title": "Inconsistent treatment difference values",
      "page": 85,
      "quote": "The assumed treatment difference of 24% is based on the effect of 26% observed in dupilumab phase 3 monotherapy studies",
      "severity": "minor"
    },
    {
      "title": "Inconsistent treatment-emergent period definition",
      "page": 89,
      "quote": "The treatment-emergent period is defined as the day from first dose of study drug to end of study. The treatment-emergent period includes the 16-week treatment period and 12-week follow-up period.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent week 16 visit day calculation",
      "page": 89,
      "quote": "Treatment period: date of the first dose of study drug to week 16 visit date (study day 113 starting from the first dose of study drug if week 16 visit date is unavailable)",
      "severity": "minor"
    },
    {
      "title": "Inconsistent treatment exposure duration calculation",
      "page": 90,
      "quote": "The duration of exposure during the study will be presented by treatment group and calculated as: (Date of last study drug injection – date of first study drug injection) + 14 days",
      "severity": "minor"
    },
    {
      "title": "Inconsistent primary analysis timing",
      "page": 91,
      "quote": "The unblinded primary analysis may be performed once all patients in the study have completed the 16-week treatment period.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent statement about alpha adjustment",
      "page": 91,
      "quote": "Hence there will be no need for alpha adjustment due to the primary analysis.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent statement about primary analysis and follow-up",
      "page": 91,
      "quote": "This primary analysis will be considered the final analysis for the primary and secondary efficacy endpoints.",
      "severity": "minor"
